(109, 1, '2025-09-02 15:18:29', '2025-09-02 15:18:29', '{\n    \"nav_menu_item[107]\": {\n        \"value\": {\n            \"menu_item_parent\": 0,\n            \"object_id\": 95,\n            \"object\": \"page\",\n            \"type\": \"post_type\",\n            \"type_label\": \"Trang b\\u00e0i vi\\u1ebft\",\n            \"url\": \"http://localhost/ekart/tin-cong-nghe/\",\n            \"title\": \"\",\n            \"target\": \"\",\n            \"attr_title\": \"\",\n            \"description\": \"\",\n            \"classes\": \"\",\n            \"xfn\": \"\",\n            \"nav_menu_term_id\": 19,\n            \"position\": 3,\n            \"status\": \"publish\",\n            \"original_title\": \"Tin c\\u00f4ng ngh\\u1ec7\",\n            \"_invalid\": false\n        },\n        \"type\": \"nav_menu_item\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-09-02 15:18:29\"\n    },\n    \"nav_menu_item[108]\": {\n        \"value\": {\n            \"menu_item_parent\": 0,\n            \"object_id\": 11,\n            \"object\": \"page\",\n            \"type\": \"post_type\",\n            \"type_label\": \"Trang\",\n            \"url\": \"http://localhost/ekart/hoan-tien-tra-hang/\",\n            \"title\": \"\",\n            \"target\": \"\",\n            \"attr_title\": \"\",\n            \"description\": \"\",\n            \"classes\": \"\",\n            \"xfn\": \"\",\n            \"nav_menu_term_id\": 19,\n            \"position\": 4,\n            \"status\": \"publish\",\n            \"original_title\": \"Ch\\u00ednh s\\u00e1ch \\u0111\\u1ed5i tr\\u1ea3 h\\u00e0ng\",\n            \"_invalid\": false\n        },\n        \"type\": \"nav_menu_item\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-09-02 15:18:29\"\n    },\n    \"nav_menu_item[-4995390661222456000]\": {\n        \"value\": {\n            \"object_id\": 105,\n            \"object\": \"page\",\n            \"menu_item_parent\": 0,\n            \"position\": 2,\n            \"type\": \"post_type\",\n            \"title\": \"About us\",\n            \"url\": \"http://localhost/ekart/about-us/\",\n            \"target\": \"\",\n            \"attr_title\": \"\",\n            \"description\": \"\",\n            \"classes\": \"\",\n            \"xfn\": \"\",\n            \"status\": \"publish\",\n            \"original_title\": \"About us\",\n            \"nav_menu_term_id\": 19,\n            \"_invalid\": false,\n            \"type_label\": \"Trang\"\n        },\n        \"type\": \"nav_menu_item\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-09-02 15:18:29\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '684d200e-4801-4b02-bb80-afe227c19677', '', '', '2025-09-02 15:18:29', '2025-09-02 15:18:29', '', 0, 'http://localhost/ekart/684d200e-4801-4b02-bb80-afe227c19677/', 0, 'customize_changeset', '', 0),
