(248, 1, '2025-09-18 07:29:35', '0000-00-00 00:00:00', 'add_action(\'admin_init\', function () {\r\n    // Redirect any user trying to access comments page\r\n    global $pagenow;\r\n    \r\n    if ($pagenow === \'edit-comments.php\') {\r\n        wp_safe_redirect(admin_url());\r\n        exit;\r\n    }\r\n\r\n    // Remove comments metabox from dashboard\r\n    remove_meta_box(\'dashboard_recent_comments\', \'dashboard\', \'normal\');\r\n\r\n    // Disable support for comments and trackbacks in post types\r\n    foreach (get_post_types() as $post_type) {\r\n        if (post_type_supports($post_type, \'comments\')) {\r\n            remove_post_type_support($post_type, \'comments\');\r\n            remove_post_type_support($post_type, \'trackbacks\');\r\n        }\r\n    }\r\n});\r\n\r\n// Close comments on the front-end\r\nadd_filter(\'comments_open\', \'__return_false\', 20, 2);\r\nadd_filter(\'pings_open\', \'__return_false\', 20, 2);\r\n\r\n// Hide existing comments\r\nadd_filter(\'comments_array\', \'__return_empty_array\', 10, 2);\r\n\r\n// Remove comments page in menu\r\nadd_action(\'admin_menu\', function () {\r\n    remove_menu_page(\'edit-comments.php\');\r\n});\r\n\r\n// Remove comments links from admin bar\r\nadd_action(\'init\', function () {\r\n    if (is_admin_bar_showing()) {\r\n        remove_action(\'admin_bar_menu\', \'wp_admin_bar_comments_menu\', 60);\r\n    }\r\n});', 'Completely Disable Comments', '', 'draft', 'closed', 'closed', '', '', '', '', '2025-09-18 07:29:35', '0000-00-00 00:00:00', '', 0, 'http://localhost/ekart/?post_type=wpcode&p=248', 0, 'wpcode', '', 0),
(249, 1, '2025-09-18 07:31:16', '0000-00-00 00:00:00', 'add_filter(\'wp_handle_upload\', \'convert_image_to_webp\', 10, 2);\r\n\r\nfunction convert_image_to_webp($upload, $context) {\r\n    // Chỉ xử lý khi upload thành công\r\n    if ($upload && isset($upload[\'file\'])) {\r\n        $file_path = $upload[\'file\'];\r\n        $file_info = pathinfo($file_path);\r\n        $extension = strtolower($file_info[\'extension\']);\r\n\r\n        // Chỉ xử lý ảnh JPG & PNG\r\n        if (in_array($extension, [\'jpg\', \'jpeg\', \'png\'])) {\r\n            $image = null;\r\n\r\n            if ($extension === \'png\') {\r\n                $image = imagecreatefrompng($file_path);\r\n                imagepalettetotruecolor($image);\r\n                imagealphablending($image, true);\r\n                imagesavealpha($image, true);\r\n            } else {\r\n                $image = imagecreatefromjpeg($file_path);\r\n            }\r\n\r\n            if ($image) {\r\n                $webp_path = $file_info[\'dirname\'] . \'/\' . $file_info[\'filename\'] . \'.webp\';\r\n\r\n                // Chất lượng WebP (0 - 100)\r\n                imagewebp($image, $webp_path, 85);\r\n                imagedestroy($image);\r\n\r\n                // Xoá file gốc, chỉ giữ WebP (nếu muốn)\r\n                unlink($file_path);\r\n\r\n                // Cập nhật đường dẫn trả về thành file WebP\r\n                $upload[\'file\'] = $webp_path;\r\n                $upload[\'url\']  = str_replace($file_info[\'basename\'], $file_info[\'filename\'] . \'.webp\', $upload[\'url\']);\r\n                $upload[\'type\'] = \'image/webp\';\r\n            }\r\n        }\r\n    }\r\n    return $upload;\r\n}\r\n', 'Convert to WebP', '', 'draft', 'closed', 'closed', '', '', '', '', '2025-09-18 07:31:16', '0000-00-00 00:00:00', '', 0, 'http://localhost/ekart/?post_type=wpcode&p=249', 0, 'wpcode', '', 0),
(250, 1, '2025-09-18 07:34:47', '2025-09-18 07:34:47', '<div class=\"ksp-content p-2 mb-2\">\r\n<h3 data-start=\"252\" data-end=\"302\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"256\" data-end=\"302\">MacBook Air 13 M4 - Tinh Tế &amp; Mạnh Mẽ</strong></span></h3>\r\n<h4 data-start=\"304\" data-end=\"329\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"309\" data-end=\"329\">Đặc điểm nổi bật</strong></span></h4>\r\n<ul data-start=\"331\" data-end=\"874\">\r\n 	<li data-start=\"331\" data-end=\"449\">\r\n<p data-start=\"333\" data-end=\"449\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"333\" data-end=\"359\">Thiết kế siêu mỏng nhẹ</strong></span><br data-start=\"359\" data-end=\"362\" /><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Độ dày chỉ 1.13 cm và trọng lượng 1.24 kg, mang lại sự tiện lợi tối ưu khi di chuyển.</span></p>\r\n</li>\r\n 	<li data-start=\"451\" data-end=\"604\">\r\n<p data-start=\"453\" data-end=\"604\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"453\" data-end=\"478\">Chip Apple M4 mạnh mẽ</strong></span><br data-start=\"478\" data-end=\"481\" /><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Được trang bị chip M4 thế hệ mới nhất với 10 nhân CPU và 8 nhân GPU, cho hiệu năng vượt trội và khả năng đồ họa ấn tượng.</span></p>\r\n</li>\r\n 	<li data-start=\"606\" data-end=\"727\">\r\n<p data-start=\"608\" data-end=\"727\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"608\" data-end=\"632\">RAM 16GB &amp; SSD 256GB</strong></span><br data-start=\"632\" data-end=\"635\" /><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Tăng cường khả năng đa nhiệm, khởi động nhanh chóng và lưu trữ đủ cho công việc hàng ngày.</span></p>\r\n</li>\r\n 	<li data-start=\"729\" data-end=\"874\">\r\n<p data-start=\"731\" data-end=\"874\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"731\" data-end=\"767\">Màn hình Liquid Retina 13.6 inch</strong></span><br data-start=\"767\" data-end=\"770\" /><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Độ phân giải 2560x1664 pixels với hình ảnh sắc nét, màu sắc chân thực và độ sáng cao lên đến 500 nits.</span></p>\r\n</li>\r\n</ul>\r\n\r\n<hr data-start=\"876\" data-end=\"879\" />\r\n\r\n<h3 data-start=\"881\" data-end=\"915\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"885\" data-end=\"915\">Thông Số Cấu Hình Chi Tiết</strong></span></h3>\r\n<h4 data-start=\"917\" data-end=\"943\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"922\" data-end=\"943\">Hiệu Năng Mạnh Mẽ</strong></span></h4>\r\n<ul data-start=\"944\" data-end=\"1136\">\r\n 	<li data-start=\"944\" data-end=\"994\">\r\n<p data-start=\"946\" data-end=\"994\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"946\" data-end=\"963\">Chip Apple M4</strong> với 10 nhân CPU và 8 nhân GPU.</span></p>\r\n</li>\r\n 	<li data-start=\"995\" data-end=\"1071\">\r\n<p data-start=\"997\" data-end=\"1071\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"997\" data-end=\"1009\">RAM 16GB</strong> giúp mở nhiều ứng dụng cùng lúc và chuyển đổi tác vụ mượt mà.</span></p>\r\n</li>\r\n 	<li data-start=\"1072\" data-end=\"1136\">\r\n<p data-start=\"1074\" data-end=\"1136\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1074\" data-end=\"1087\">SSD 256GB</strong> giúp khởi động nhanh và lưu trữ đầy đủ tài liệu.</span></p>\r\n</li>\r\n</ul>\r\n<h4 data-start=\"1138\" data-end=\"1163\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1143\" data-end=\"1163\">Màn Hình Sắc Nét</strong></span></h4>\r\n<ul data-start=\"1164\" data-end=\"1311\">\r\n 	<li data-start=\"1164\" data-end=\"1228\">\r\n<p data-start=\"1166\" data-end=\"1228\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1166\" data-end=\"1193\">13.6 inch Liquid Retina</strong> với độ phân giải 2560x1664 pixels.</span></p>\r\n</li>\r\n 	<li data-start=\"1229\" data-end=\"1311\">\r\n<p data-start=\"1231\" data-end=\"1311\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Độ sáng lên đến <strong data-start=\"1247\" data-end=\"1259\">500 nits</strong> cho khả năng hiển thị trong mọi điều kiện ánh sáng.</span></p>\r\n</li>\r\n</ul>\r\n\r\n<hr data-start=\"1313\" data-end=\"1316\" />\r\n\r\n<h3 data-start=\"1318\" data-end=\"1344\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1322\" data-end=\"1344\">Trong Hộp Sản Phẩm</strong></span></h3>\r\n<ul data-start=\"1345\" data-end=\"1528\">\r\n 	<li data-start=\"1345\" data-end=\"1370\">\r\n<p data-start=\"1347\" data-end=\"1370\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1347\" data-end=\"1370\">MacBook Air 13 inch</strong></span></p>\r\n</li>\r\n 	<li data-start=\"1371\" data-end=\"1492\">\r\n<p data-start=\"1373\" data-end=\"1492\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1373\" data-end=\"1404\">Bộ Tiếp Hợp Nguồn USB-C 30W</strong> (M4 với GPU 8 lõi)</span><br data-start=\"1423\" data-end=\"1426\" /><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Hoặc</span><br data-start=\"1432\" data-end=\"1435\" /><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1437\" data-end=\"1472\">Bộ Tiếp Hợp Nguồn USB-C Kép 35W</strong> (M4 với GPU 10 lõi)</span></p>\r\n</li>\r\n 	<li data-start=\"1493\" data-end=\"1528\">\r\n<p data-start=\"1495\" data-end=\"1528\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1495\" data-end=\"1528\">Cáp USB-C sang MagSafe 3 (2m)</strong></span></p>\r\n</li>\r\n</ul>\r\n\r\n<hr data-start=\"1530\" data-end=\"1533\" />\r\n\r\n<h3 data-start=\"1535\" data-end=\"1573\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1539\" data-end=\"1573\">Tùy Chọn Cấu Hình Theo Yêu Cầu</strong></span></h3>\r\n<div class=\"_tableContainer_1rjym_1\">\r\n<div class=\"group _tableWrapper_1rjym_13 flex w-fit flex-col-reverse\" tabindex=\"-1\">\r\n<table class=\"w-fit min-w-(--thread-content-width)\" data-start=\"1575\" data-end=\"2428\">\r\n<thead data-start=\"1575\" data-end=\"1746\">\r\n<tr data-start=\"1575\" data-end=\"1746\">\r\n<th data-start=\"1575\" data-end=\"1619\" data-col-size=\"sm\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1577\" data-end=\"1590\">Phiên bản</strong></span></th>\r\n<th data-start=\"1619\" data-end=\"1642\" data-col-size=\"sm\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1621\" data-end=\"1628\">Giá</strong></span></th>\r\n<th data-start=\"1642\" data-end=\"1746\" data-col-size=\"md\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1644\" data-end=\"1656\">Cấu Hình</strong></span></th>\r\n</tr>\r\n</thead>\r\n<tbody data-start=\"1916\" data-end=\"2428\">\r\n<tr data-start=\"1916\" data-end=\"2086\">\r\n<td data-start=\"1916\" data-end=\"1959\" data-col-size=\"sm\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1918\" data-end=\"1936\">Từ 26.999.000đ</strong></span></td>\r\n<td data-start=\"1959\" data-end=\"1983\" data-col-size=\"sm\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"1961\" data-end=\"1976\">10CPU, 8GPU</strong></span></td>\r\n<td data-start=\"1983\" data-end=\"2086\" data-col-size=\"md\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Bộ nhớ 24GB hoặc 32GB, SSD 512GB, 1TB, hoặc 2TB, Bộ Tiếp Hợp Nguồn USB-C 35W hoặc 70W</span></td>\r\n</tr>\r\n<tr data-start=\"2087\" data-end=\"2257\">\r\n<td data-start=\"2087\" data-end=\"2130\" data-col-size=\"sm\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"2089\" data-end=\"2107\">Từ 31.999.000đ</strong></span></td>\r\n<td data-start=\"2130\" data-end=\"2154\" data-col-size=\"sm\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"2132\" data-end=\"2148\">10CPU, 10GPU</strong></span></td>\r\n<td data-start=\"2154\" data-end=\"2257\" data-col-size=\"md\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Bộ nhớ 24GB hoặc 32GB, SSD 1TB hoặc 2TB, Bộ Tiếp Hợp Nguồn USB-C 70W</span></td>\r\n</tr>\r\n<tr data-start=\"2258\" data-end=\"2428\">\r\n<td data-start=\"2258\" data-end=\"2301\" data-col-size=\"sm\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"2260\" data-end=\"2278\">Từ 36.999.000đ</strong></span></td>\r\n<td data-start=\"2301\" data-end=\"2325\" data-col-size=\"sm\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"2303\" data-end=\"2319\">10CPU, 10GPU</strong></span></td>\r\n<td data-start=\"2325\" data-end=\"2428\" data-col-size=\"md\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Bộ nhớ 32GB, SSD 1TB hoặc 2TB, Bộ Tiếp Hợp Nguồn USB-C 70W</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n\r\n<hr data-start=\"2430\" data-end=\"2433\" />\r\n\r\n<h3 data-start=\"2435\" data-end=\"2460\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"2439\" data-end=\"2460\">Tính Năng Nổi Bật</strong></span></h3>\r\n<ul data-start=\"2461\" data-end=\"2792\">\r\n 	<li data-start=\"2461\" data-end=\"2569\">\r\n<p data-start=\"2463\" data-end=\"2569\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"2463\" data-end=\"2491\">Hiệu suất đồ họa mạnh mẽ</strong>: 8 nhân GPU cho khả năng chỉnh sửa ảnh, biên tập video và giải trí tuyệt vời.</span></p>\r\n</li>\r\n 	<li data-start=\"2570\" data-end=\"2686\">\r\n<p data-start=\"2572\" data-end=\"2686\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"2572\" data-end=\"2598\">Tốc độ SSD nhanh chóng</strong>: Khởi động máy tính gần như ngay lập tức, tải ứng dụng và sao chép dữ liệu nhanh chóng.</span></p>\r\n</li>\r\n 	<li data-start=\"2687\" data-end=\"2792\">\r\n<p data-start=\"2689\" data-end=\"2792\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"2689\" data-end=\"2725\">Màn hình Liquid Retina sống động</strong>: Độ phân giải cao và độ sáng tối ưu cho trải nghiệm xem tuyệt vời.</span></p>\r\n</li>\r\n</ul>\r\n\r\n<hr data-start=\"2794\" data-end=\"2797\" />\r\n\r\n<h3 data-start=\"2799\" data-end=\"2815\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><strong data-start=\"2803\" data-end=\"2815\">Tổng Kết</strong></span></h3>\r\n<p data-start=\"2816\" data-end=\"3060\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">MacBook Air 13 M4 2025 là sự kết hợp hoàn hảo giữa thiết kế mỏng nhẹ, hiệu năng mạnh mẽ và màn hình chất lượng cao. Với nhiều lựa chọn cấu hình linh hoạt, bạn có thể dễ dàng tùy chỉnh máy để phù hợp với nhu cầu công việc hoặc giải trí của mình.</span></p>\r\n\r\n</div>', 'MacBook Air M4 13Inch', '', 'inherit', 'closed', 'closed', '', '228-autosave-v1', '', '', '2025-09-18 07:34:47', '2025-09-18 07:34:47', '', 228, 'http://localhost/ekart/?p=250', 0, 'revision', '', 0);
